update cellar.products set age_years = 5.0, age_label = '5 yr', nas = false, image_url = coalesce(image_url, 'https://static.wixstatic.com/media/db1851_4cc89ab44cd946cfa9e4820c8cbb2c0f~mv2.png/v1/fill/w_2500,h_2500,al_c/db1851_4cc89ab44cd946cfa9e4820c8cbb2c0f~mv2.png'), producer = coalesce(producer, 'Heaven''s Door'), producer_id = coalesce(producer_id, '19a0b6ce-9286-493c-aeca-44ec5363ac6d'::uuid), source = 'maker', source_url = 'https://www.heavensdoor.com/double-barrel-whiskey', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '9787f079-8f38-49b7-bed5-7e684235d386' and facts_verified_at is null;
update cellar.products set age_years = 6.0, age_label = '6 yr', nas = false, image_url = coalesce(image_url, 'https://static.wixstatic.com/media/db1851_0788c477b6de4f22882b6ce0997c0444~mv2.png/v1/fill/w_2500,h_2500,al_c/db1851_0788c477b6de4f22882b6ce0997c0444~mv2.png'), name = 'Heaven''s Door Rye', expression = 'Rye', aliases = (select array_agg(distinct a) from unnest(array_append(aliases, 'Heaven''s Door Finished in Vosges Oak Barrels Rye')) a), producer = coalesce(producer, 'Heaven''s Door'), producer_id = coalesce(producer_id, '19a0b6ce-9286-493c-aeca-44ec5363ac6d'::uuid), source = 'maker', source_url = 'https://www.heavensdoor.com/straight-rye-whiskey', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '702fb038-4fdb-43c6-92d3-6b6a33c0488e' and facts_verified_at is null;
